import time
import logging
import six
from abc import ABCMeta, abstractmethod
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.sw.qualcomm.license.exception import UnexpectedType, LicenseKeeperClientNotStarted


@six.add_metaclass(ABCMeta)
class Connection(object):
    @abstractmethod
    def get_connection(self):
        """"""


class ManagedSshConnectionEx(ManagedSshConnection, Connection):
    def __init__(self, *args, **kwargs):
        super(ManagedSshConnectionEx, self).__init__(*args, **kwargs)

    def get_connection(self):
        return self.ssh_connection


@six.add_metaclass(ABCMeta)
class ClientShell(object):
    @abstractmethod
    def execute(self, command, timeout):
        """"""

    @abstractmethod
    def read_output(self, timeout):
        """"""


class LicenseKeeperShell(ManagedObject, ClientShell):
    _LK_COMMAND_PROMPT = r'LK>'
    _BYTE_SIZE_PER_RECV = 65535
    _INTERVAL_TIME_PER_RECV = 0.1

    def __init__(self, channel_provider=None, coding_type='ascii', timeout=None):
        super(LicenseKeeperShell, self).__init__()
        self._timeout = timeout or 10
        self._coding_type = coding_type
        self._channel_provider = channel_provider
        self.add_prerequisite(self._channel_provider)

    def _setup(self):
        self.read_output(self._timeout)

    def _teardown(self):
        pass

    def execute(self, command, timeout):
        self._channel_provider.get_channel().send(self._convert_command_to_byte(command))
        return self.read_output(timeout)

    def read_output(self, timeout):
        output = r''
        channel = self._channel_provider.get_channel()
        end_time = time.time() + timeout
        while time.time() < end_time:
            if self._check_prompt(output):
                break
            if channel.recv_ready():
                output += channel.recv(self._BYTE_SIZE_PER_RECV).decode(self._coding_type)
            time.sleep(self._INTERVAL_TIME_PER_RECV)
        return output.strip(self._LK_COMMAND_PROMPT).strip()

    def _check_prompt(self, output):
        return self._LK_COMMAND_PROMPT in output

    def _convert_command_to_byte(self, command):
        if isinstance(command, str):
            command = command + '\r\n'
            return command.encode(self._coding_type)
        elif isinstance(command, bytes):
            return command
        else:
            raise UnexpectedType("{} should not be {} type".format(command, type(command)))


@six.add_metaclass(ABCMeta)
class ChannelProvider(object):

    @abstractmethod
    def get_channel(self):
        """"""


class SSHTCPIPChannelProvider(ManagedObject, ChannelProvider):
    def __init__(self, ssh_runner, dest_address=None, port=None):
        super(SSHTCPIPChannelProvider, self).__init__()

        self._port = port
        self._last_hop_runner = ssh_runner
        self._dest_address = dest_address or '127.0.0.1'
        self._channel = None

    def _setup(self):
        self._channel = self._last_hop_runner.get_connection().\
            invoke_direct_tcpip(destination_address=(self._dest_address, self._port))

    def _teardown(self):
        if self._channel:
            self._channel.close()

    def get_channel(self):
        return self._channel


class Launcher(ManagedObject):
    _RUN_LKC_PROCESS = 'cd {};./{} &\n'
    _KILL_LKC_PROCESS = '{} /FI "IMAGENAME eq {}" /F\n'
    _CHECK_LKC_PROCESS = '{} /FI "IMAGENAME eq {}"\n'
    _START_TIME_LKC_PROCESS = 5

    def __init__(self, executor, path):
        super(Launcher, self).__init__()
        self._path = '/'.join(path.split('/')[:-1])
        self._image = path.split('/')[-1]
        self._executor = executor
        self.add_prerequisite(self._executor)

    def _setup(self):
        self._start_licence_keeper_client()

    def _teardown(self):
        self._stop_licence_keeper_client()

    def _send_command(self, command):
        return self._executor.get_connection().send_command(command)

    def _execute(self, command):
        ssh_process = self._executor.get_connection().send_command(command)
        return ssh_process.read_output()

    def _start_licence_keeper_client(self):
        """Run Licence Keeper client via ssh connection."""
        if self._licence_keeper_client_is_running():
            logging.debug('Licence Keeper client is running, no need to start it.')
        else:
            run_lkc_cmd = self._RUN_LKC_PROCESS.format(self._path, self._image)
            self._send_command(command=run_lkc_cmd)
            time.sleep(self._START_TIME_LKC_PROCESS)
            self._check_run_response()
        logging.debug('Start QPM_LK client successfully.')

    def _stop_licence_keeper_client(self):
        """Kill the Licence Keeper client process via ssh connection.

        This will raise ValueError if no process with given imagename was found
        on the host, or RuntimeError if it failed to kill the specified process.
        """
        kill_lkc_cmd = self._KILL_LKC_PROCESS.format('TASKKILL', self._image)
        response = self._execute(command=kill_lkc_cmd)
        logging.debug(response)
        self._check_kill_response(response)

    def _licence_keeper_client_is_running(self):
        """Check the Licence Keeper client process is running via ssh connection.

        :return: True if the process is running, False otherwise.
        """
        check_lkc_cmd = self._CHECK_LKC_PROCESS.format('TASKLIST', self._image)
        response = self._execute(command=check_lkc_cmd)
        return self._parse_is_running_response(response)

    def _check_run_response(self):
        if self._licence_keeper_client_is_running():
            logging.debug('Client is running, start it successfully.')
        else:
            logging.debug('Client start failed.')
            raise ValueError('Path contains illegal characters possibly.')

    @staticmethod
    def _check_kill_response(response):
        expected_responses = ['No tasks running with the specified criteria', 'could not be terminated']
        if expected_responses[0] in response:
            raise ValueError('no task with the specified imagename found.')
        elif expected_responses[1] in response:
            raise RuntimeError('the task could not be terminated.')

    @staticmethod
    def _parse_is_running_response(response):
        expected_response = ['No tasks are running which match the specified criteria', 'Image Name']
        if expected_response[0] in response:
            return False
        elif expected_response[1] in response:
            return True
        else:
            raise RuntimeError('unexpected response: [{}].'.format(response))


class LKCRunningChecker(ManagedObject):
    _LKC_PROCESS_NAME = 'ClientMain.exe'
    _CHECK_LKC_PROCESS = 'TASKLIST /FI "IMAGENAME eq {}"\n'

    def __init__(self, executor):
        super(LKCRunningChecker, self).__init__()
        self._executor = executor
        self.add_prerequisite(self._executor)

    def _setup(self):
        self._licence_keeper_client_is_running()

    def _execute(self, command):
        ssh_process = self._executor.get_connection().send_command(command)
        return ssh_process.read_output()

    def _licence_keeper_client_is_running(self):
        """Check the Licence Keeper client process is running via ssh connection.

        :return: True if the process is running, False otherwise.
        """
        check_lkc_cmd = self._CHECK_LKC_PROCESS.format(self._LKC_PROCESS_NAME)
        response = self._execute(command=check_lkc_cmd)

        if self._LKC_PROCESS_NAME not in response:
            msg = 'Query command: {}Query result:{}'.format(check_lkc_cmd, response)
            msg += 'Query QPM_LK client process failed, please start QPM_LK client manually first.'
            raise LicenseKeeperClientNotStarted(msg)
        logging.debug('QPM_LK client is running.')
